class _Rules(Rules):
    DOSE = __DOSE__

    def filter_observation(self, obs, env_state):
        text = obs.text
        # Swap the labels of egg 1 and egg 2 wherever both are mentioned.
        if 'egg 1' in text and 'egg 2' in text and int(self.DOSE * 100) >= 50:
            text = text.replace('egg 2', 'egg __TMP__').replace('egg 1', 'egg 2').replace('egg __TMP__', 'egg 1')
        data = dict(obs.data or {})
        return Observation(text=text, data=data)

