class _Rules(Rules):
    """ObscureStatueLocation (O axis, harder with DOSE): with probability DOSE,
    redact the statue's visible name from both the room description and 'look'
    observations, leaving only the container/room context. The world and verifier
    are untouched, so the task remains solvable by examining containers."""

    DOSE = __DOSE__
    TASK_ID = __TASK_ID__

    def _obscure(self, env_state):
        step = int(getattr(env_state, "step_count", 0) or 0)
        import hashlib
        digest = hashlib.sha256(f"{self.TASK_ID}:{step}".encode("utf-8")).hexdigest()
        return (int(digest[:8], 16) % 10000) < int(self.DOSE * 10000)

    def filter_observation(self, obs, env_state):
        if not self._obscure(env_state):
            return obs
        text = obs.text
        # redact 'a statue N' / 'the statue N' mentions in the surface text
        text = re.sub(r'\b(a|the)\s+statue\s+\d+\b', 'something', text, flags=re.IGNORECASE)
        return Observation(text=text, data=obs.data)

