class _Rules(Rules):
    """ScrambleRoomLabels (O axis, harder with DOSE): with probability DOSE,
    replace numeric container labels in the observation text (e.g. 'shelf 2',
    'sidetable 1') with generic placeholders, so the policy cannot rely on the
    exact destination strings. World and verifier unchanged; solvable by examine."""

    DOSE = __DOSE__
    TASK_ID = __TASK_ID__

    def _scramble(self, env_state):
        step = int(getattr(env_state, "step_count", 0) or 0)
        import hashlib
        digest = hashlib.sha256(f"{self.TASK_ID}:{step}".encode("utf-8")).hexdigest()
        return (int(digest[:8], 16) % 10000) < int(self.DOSE * 10000)

    def filter_observation(self, obs, env_state):
        if not self._scramble(env_state):
            return obs
        text = obs.text
        text = re.sub(r'\b(shelf|sidetable|coffeetable|armchair|sofa|garbagecan)\s+\d+\b',
                      r'\1 ?', text, flags=re.IGNORECASE)
        return Observation(text=text, data=obs.data)

class _Rules(Rules):
    """RelocateTargetAlarmclocks (A axis, harder with DOSE): with probability DOSE, move the two
    target alarmclocks from shelf 1 to other containers before the episode starts. At DOSE=0 the
    environment is unchanged and the task remains solvable at DOSE=1 (the alarmclocks still exist
    and can be retrieved and moved to the desk)."""

    DOSE = __DOSE__

    def filter_observation(self, obs, env_state):
        text = obs.text
        if "On the shelf 1, you see " in text:
            # remove the two target alarmclocks from shelf 1 description
            text = text.replace(" a alarmclock 2,", "").replace(" a alarmclock 1,", "")
        return Observation(text=text, data=obs.data)
